struct statistics_time_parts_t { int seconds; int minutes; int hours; };
static __inline statistics_time_parts_t statistics_time_parts(int ms) {
    int seconds = ms / 1000;
    int minutes = seconds / 60;
    int hours = minutes / 60;
    minutes -= hours * 60;
    seconds -= minutes * 60;
    statistics_time_parts_t parts = { seconds, minutes, hours };
    return parts;
}

